package org.junit.jupiter.api; public final class Assertions { public static void assertTrue(boolean b){if(!b)throw new AssertionError("expected true");} public static void assertFalse(boolean b){if(b)throw new AssertionError("expected false");} public static void assertEquals(Object e,Object a){if(e==null?a!=null:!e.equals(a))throw new AssertionError("expected "+e+" got "+a);} public static void assertEquals(long e,long a){if(e!=a)throw new AssertionError("expected "+e+" got "+a);} public static void assertNotSame(Object e,Object a){if(e==a)throw new AssertionError("expected different objects");} public static void assertNotNull(Object o){if(o==null)throw new AssertionError("expected non-null");} public static void assertDoesNotThrow(Runnable r){try{r.run();}catch(Throwable t){throw new AssertionError(t);}} }
